-- Business records: no DELETE for the runtime (documents and transactions are kept; a wrong link is
-- undone by an update).
GRANT SELECT, INSERT, UPDATE ON vendor, transaction, transaction_line, document TO cs_runtime;
--> statement-breakpoint
-- Immutable history (CLAUDE.md invariant 3): extractions and their lines are only ever inserted.
GRANT SELECT, INSERT ON doc_extraction, doc_line TO cs_runtime;
--> statement-breakpoint
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'vendor', 'transaction', 'transaction_line', 'document', 'doc_extraction', 'doc_line'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO PUBLIC '
      'USING (tenant_id = any(app_tenant_ids())) '
      'WITH CHECK (tenant_id = any(app_tenant_ids()))', t);
  END LOOP;
END
$$;
--> statement-breakpoint
CREATE TRIGGER doc_extraction_immutable BEFORE UPDATE OR DELETE ON doc_extraction
  FOR EACH ROW EXECUTE FUNCTION forbid_update_except();
--> statement-breakpoint
CREATE TRIGGER doc_line_immutable BEFORE UPDATE OR DELETE ON doc_line
